    tone: 'professional',
    discountPercent: 0,
  });

  // Pricing data
  const pricingTiers = {
    studio: 150,
    apartment: 250,
    villa: 500,
  };

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);

    // Validate
    const parsed = CampaignSchema.safeParse(formData);
    if (!parsed.success) {
      setError('يرجى التحقق من البيانات المدخلة');
      return;
    }

    // Track event in PostHog
    posthog?.capture('campaign_generation_started', {
      serviceType: formData.serviceType,
      emirate: formData.emirate,
      tone: formData.tone,
    });

    startTransition(async () => {
      try {
        const data = await createCampaignAction(new FormData(
          Object.entries(formData).reduce((fd, [key, value]) => {
            fd.append(key, String(value));
            return fd;
          }, new FormData())
        ));

        setResult(data as CampaignResult);

        // Track success
        posthog?.capture('campaign_generated_success', {
